use sketchpad_rs::document::{Document,records};use std::{fs,env};
fn main(){let a:Vec<_>=env::args().collect();let b=fs::read(&a[1]).unwrap();let doc=Document::from_bytes(&b,None).unwrap();let rs=records(&b).unwrap();for arg in &a[2..]{let id:usize=arg.parse().unwrap();let o=&doc.objects[id-1];let at=o.header_offset.unwrap();let i=rs.iter().position(|r|r.kind==0x7d0&&r.data.start==at).unwrap();let end=(i..rs.len()).find(|&i|rs[i].kind==0x7d7).unwrap();println!("OBJECT {id} {:?}",o.kind);for r in &rs[i..=end]{println!("RECORD {:04x} len{} {:?}",r.kind,r.data.len(),&b[r.data.clone()])}}}
